SELECT FROM opc_community_module
status != 'DELETED'
AND category = #{category}
AND (name LIKE CONCAT('%', #{keyword}, '%') OR code LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY install_count DESC, rating DESC, id DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE opc_community_module
name = #{name}, description = #{description}, icon = #{icon}, tags = #{tags}, status = #{status}, update_time = NOW()
WHERE id = #{id}
